cd /tmp && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Start a transaction
const transaction = db.transaction(() => {
  // 1. Update store credit balance: 66 + 88 = 154
  db.prepare(\"UPDATE users SET store_credit_balance = store_credit_balance + 88 WHERE user_id = 'user_d3d5d0c8'\").run();

  // 2. Update the item status to reflect the exchange couldn't be completed (out of stock)
  db.prepare(\"UPDATE order_items SET item_status = 'returned', refund_amount = 88, refund_method = 'store_credit', store_credit_only = 1 WHERE oi_id = 'ITEM-59FB3E'\").run();

  // Verify updates
  const user = db.prepare(\"SELECT name, store_credit_balance FROM users WHERE user_id = 'user_d3d5d0c8'\").get();
  const item = db.prepare(\"SELECT oi_id, name, item_status, refund_amount, refund_method, store_credit_only FROM order_items WHERE oi_id = 'ITEM-59FB3E'\").get();

  console.log('=== UPDATED USER ===');
  console.log(JSON.stringify(user, null, 2));
  console.log('\n=== UPDATED ITEM ===');
  console.log(JSON.stringify(item, null, 2));
});

transaction();
console.log('\nTransaction committed successfully.');
"
